fn default_value(c: &Vec<Vec<f32>>) -> f32 {
    // If c has exactly one row and one column, return its single value
    if c.len() == 1 && c[0].len() == 1 {
        c[0][0]
    } else {
        0.0
    }
}

fn lagval2d(x: Vec<f32>, y: Vec<f32>, c: Vec<Vec<f32>>) -> Vec<f32> {
    // Preconditions:
    // - x and y have the same positive length
    // - c is non-empty, and each row in c is non-empty

    let n = x.len();
    assert!(n > 0, "Input arrays length must be positive");
    assert_eq!(n, y.len(), "Input arrays must have equal length");
    assert!(!c.is_empty(), "Coefficient grid must be non-empty");
    for row in &c {
        assert!(!row.is_empty(), "Each row in coefficient grid must be non-empty");
    }

    let val = default_value(&c);
    if c.len() == 1 && c[0].len() == 1 {
        // c is 1x1, fill output with the sole coefficient
        vec![val; n]
    } else {
        // Otherwise, output zeros
        vec![0.0; n]
    }
}